int passed = 0;
void Check(string name, bool success)
{
    if (!success) throw new Exception("FAIL: " + name);
    Console.WriteLine("PASS: " + name); passed++;
}
void Reject(string name, string json)
{
    try { ParseFixture(json); }
    catch { Check(name, true); return; }
    Check(name, false);
}
